import string
from itertools import dropwhile
from nltk import pos_tag, word_tokenize
from nltk.stem import WordNetLemmatizer


class StringConstants:
    PUNCTUATION = string.punctuation


class LeMMatization:
    POS_TAG_VERB = 'v'
    POS_TAG_ADJECTIVE = 'a'
    POS_TAG_ADVERB = 'r'

    def __init__(self):
        self.lemmatizer = WordNetLemmatizer()

    def lemmatize_sentence(self, sentence):
        clean_sentence = self.remove_punctuation(sentence)
        words = word_tokenize(clean_sentence)
        tags = self.get_pos_tags(words)
        return [self.lemmatize_word(word, tag) for word, tag in zip(words, tags)]

    def get_pos_tag(self, sentence):
        clean_sentence = self.remove_punctuation(sentence)
        words = word_tokenize(clean_sentence)
        return self.get_pos_tags(words)

    def get_pos_tags(self, words):
        return [tag for _, tag in pos_tag(words)]

    def lemmatize_word(self, word, tag):
        if tag.startswith('V'):
            return self.lemmatizer.lemmatize(word, pos=self.POS_TAG_VERB)
        elif tag.startswith('J'):
            return self.lemmatizer.lemmatize(word, pos=self.POS_TAG_ADJECTIVE)
        elif tag.startswith('R'):
            return self.lemmatizer.lemmatize(word, pos=self.POS_TAG_ADVERB)
        else:
            return self.lemmatizer.lemmatize(word)

    def remove_punctuation(self, sentence):
        return sentence.translate(str.maketrans('', '', StringConstants.PUNCTUATION))
